class GatewayMessageCreateDispatchData(BaseModel):
    model_config = ConfigDict(
        extra='allow',
    )
    id: Annotated[str, Field(description='ID of the message')]
    author: Annotated[
        APIUser,
        Field(
            description="The author of this message (only a valid user in the case where the message is generated by a user or bot user)\n\nIf the message is generated by a webhook, the author object corresponds to the webhook's id,\nusername, and avatar. You can tell if a message is generated by a webhook by checking for the `webhook_id` property"
        ),
    ]
    content: Annotated[
        str,
        Field(
            description='Contents of the message\n\nThe `MESSAGE_CONTENT` privileged gateway intent is required for verified applications to receive a non-empty value from this field\n\nIn the Discord Developers Portal, you need to enable the toggle of this intent of your application in **Bot \\> Privileged Gateway Intents**.\nYou also need to specify the intent bit value (`1 << 15`) if you are connecting to the gateway'
        ),
    ]
    timestamp: Annotated[str, Field(description='When this message was sent')]
    edited_timestamp: Annotated[
        str | None, Field(description='When this message was edited (or null if never)')
    ]
    tts: Annotated[bool, Field(description='Whether this was a TTS message')]
    mention_everyone: Annotated[
        bool, Field(description='Whether this message mentions everyone')
    ]
    mention_roles: Annotated[
        list[str], Field(description='Roles specifically mentioned in this message')
    ]
    mention_channels: Annotated[
        list[APIChannelMention] | None,
        Field(
            description='Channels specifically mentioned in this message\n\nNot all channel mentions in a message will appear in `mention_channels`.\n- Only textual channels that are visible to everyone in a public guild will ever be included\n- Only crossposted messages (via Channel Following) currently include `mention_channels` at all\n\nIf no mentions in the message meet these requirements, this field will not be sent'
        ),
    ] = None
    attachments: Annotated[
        list[APIAttachment],
        Field(
            description='Any attached files that are not referenced in embeds or components'
        ),
    ]
    embeds: Annotated[list[APIEmbed], Field(description='Any embedded content')]
    reactions: Annotated[
        list[APIReaction] | None, Field(description='Reactions to the message')
    ] = None
    nonce: Annotated[
        str | float | None,
        Field(
            description='A nonce that can be used for optimistic message sending (up to 25 characters)\n\n**You will not receive this from further fetches. This is received only once from a `MESSAGE_CREATE`\nevent to ensure it got sent**'
        ),
    ] = None
    pinned: Annotated[bool, Field(description='Whether this message is pinned')]
    webhook_id: Annotated[
        str | None,
        Field(
            description="If the message is generated by a webhook, this is the webhook's id"
        ),
    ] = None
    type: Annotated[Type15, Field(description='Type of message')]
    activity: Annotated[
        APIMessageActivity | None,
        Field(description='Sent with Rich Presence-related chat embeds'),
    ] = None
    application: Annotated[
        PartialAPIApplication | None,
        Field(description='Sent with Rich Presence-related chat embeds'),
    ] = None
    application_id: Annotated[
        str | None,
        Field(
            description="If the message is a response to an Interaction, this is the id of the interaction's application"
        ),
    ] = None
    message_reference: Annotated[
        APIMessageReference | None,
        Field(
            description='Reference data sent with crossposted messages, replies, pins, and thread starter messages'
        ),
    ] = None
    flags: Annotated[
        Flags54 | None, Field(description='Message flags combined as a bitfield')
    ] = None
    referenced_message: Annotated[
        APIMessage | None,
        Field(
            description='The message associated with the `message_reference`\n\nThis field is only returned for messages with a `type` of `19` (REPLY).\n\nIf the message is a reply but the `referenced_message` field is not present,\nthe backend did not attempt to fetch the message that was being replied to,\nso its state is unknown.\n\nIf the field exists but is `null`, the referenced message was deleted'
        ),
    ] = None
    interaction_metadata: Annotated[
        APIApplicationCommandInteractionMetadata
        | APIMessageComponentInteractionMetadata
        | APIModalSubmitInteractionMetadata
        | None,
        Field(
            description='Sent if the message is sent as a result of an interaction',
            discriminator='type',
        ),
    ] = None
    interaction: Annotated[
        APIMessageInteraction | None,
        Field(
            deprecated=True,
            description='Sent if the message is a response to an Interaction',
        ),
    ] = None
    thread: Annotated[
        APIDMChannel
        | APIGroupDMChannel
        | APIGuildCategoryChannel
        | APIGuildForumChannel
        | APIAnnouncementThreadChannel
        | APIGuildMediaChannel
        | APIGuildStageVoiceChannel
        | APIGuildVoiceChannel
        | APINewsChannel
        | APIPrivateThreadChannel
        | APIPublicThreadChannel
        | APITextChannel
        | None,
        Field(
            description='Sent if a thread was started from this message',
            discriminator='type',
        ),
    ] = None
    components: Annotated[
        list[APIMessageTopLevelComponent] | None,
        Field(
            description='Sent if the message contains components like buttons, action rows, or other interactive components\n\nThe `MESSAGE_CONTENT` privileged gateway intent is required for verified applications to receive a non-empty value from this field\n\nIn the Discord Developers Portal, you need to enable the toggle of this intent of your application in **Bot \\> Privileged Gateway Intents**.\nYou also need to specify the intent bit value (`1 << 15`) if you are connecting to the gateway'
        ),
    ] = None
    sticker_items: Annotated[
        list[APIStickerItem] | None,
        Field(description='Sent if the message contains stickers'),
    ] = None
    stickers: Annotated[
        list[APISticker] | None,
        Field(deprecated=True, description='The stickers sent with the message'),
    ] = None
    position: Annotated[
        float | None,
        Field(
            description='A generally increasing integer (there may be gaps or duplicates) that represents the approximate position of the message in a thread\n\nIt can be used to estimate the relative position of the message in a thread in company with `total_message_sent` on parent thread'
        ),
    ] = None
    role_subscription_data: Annotated[
        APIMessageRoleSubscriptionData | None,
        Field(
            description='Data of the role subscription purchase or renewal that prompted this `ROLE_SUBSCRIPTION_PURCHASE` message'
        ),
    ] = None
    resolved: Annotated[
        APIInteractionDataResolved | None,
        Field(
            description='Data for users, members, channels, and roles referenced in this message'
        ),
    ] = None
    poll: Annotated[
        APIPoll | None,
        Field(
            description='A poll!\n\nThe `MESSAGE_CONTENT` privileged gateway intent is required for verified applications to receive a non-empty value from this field\n\nIn the Discord Developers Portal, you need to enable the toggle of this intent of your application in **Bot \\> Privileged Gateway Intents**.\nYou also need to specify the intent bit value (`1 << 15`) if you are connecting to the gateway'
        ),
    ] = None
    message_snapshots: Annotated[
        list[APIMessageSnapshot] | None,
        Field(
            description='The message associated with the message_reference. This is a minimal subset of fields in a message (e.g. author is excluded.)'
        ),
    ] = None
    call: Annotated[
        APIMessageCall | None, Field(description='The call associated with the message')
    ] = None
    shared_client_theme: Annotated[
        APIMessageSharedClientTheme | None,
        Field(description='The custom client-side theme shared via the message'),
    ] = None
    channel_id: Annotated[
        str, Field(description='ID of the channel the message was sent in')
    ]
    guild_id: Annotated[
        str | None, Field(description='ID of the guild the message was sent in')
    ] = None
    member: Annotated[
        APIGuildMemberNoUser | None,
        Field(
            description="Member properties for this message's author\n\nThe member object exists in `MESSAGE_CREATE` and `MESSAGE_UPDATE` events\nfrom text-based guild channels"
        ),
    ] = None
    mentions: Annotated[
        list[APIUserWithMember],
        Field(description='Users specifically mentioned in the message'),
    ]
    channel_type: Annotated[
        ChannelType1 | None,
        Field(description='The type of channel the message was sent in'),
    ] = None


